require_once __DIR__.'/../includes/auth.php';requireAdmin();require_once __DIR__.'/../includes/mailer.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim((string)($_POST['note']??''));if(in_array($status,['approved','rejected','completed','cancelled'],true)){$q=$pdo->prepare('SELECT user_id,session_start FROM coach_bookings WHERE id=?');$q->execute([$id]);$b=$q->fetch();if($b){$pdo->prepare('UPDATE coach_bookings SET status=?,admin_message=?,reviewed_at=NOW(),reviewed_by=? WHERE id=?')->execute([$status,$note?:null,$_SESSION['user_id'],$id]);fittrackNotify($pdo,(int)$b['user_id'],'Coaching booking '.$status,'Your coaching request for '.$b['session_start'].' is '.$status.'. '.($note?:''),'FitTrack coaching booking update');}}redirect('bookings.php');}
$rows=$pdo->query('SELECT b.*,u.name user_name,u.email,c.name coach_name FROM coach_bookings b JOIN users u ON u.id=b.user_id JOIN coaches c ON c.id=b.coach_id ORDER BY b.session_start DESC')->fetchAll();$pageTitle='Coaching bookings';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">COACHING</p><h1>Coaching bookings</h1></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Coach</th><th>Session time</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><?=e($b['user_name'])?><br><small><?=e($b['email'])?></small></td><td><?=e($b['coach_name'])?></td><td><?=e($b['session_start'])?></td><td><?=e(ucfirst($b['status']))?></td><td><form method="post" class="admin-decision"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><input name="note" placeholder="Optional note"><select name="status"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="completed">Completed</option><option value="cancelled">Cancel</option></select><button class="button btn-small">Update</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
